/**
 * Funções puras para lógica de estoque, alertas e matching de produtos.
 * Extraídas dos componentes de dashboard, formulários e Requisicao.tsx
 * para permitir testes unitários isolados.
 */

// ============================================================
// Tipos
// ============================================================

/** Status de estoque para decisões de compra (view SQL) */
export type StockStatusPurchasing = 'sem_estoque' | 'critico' | 'baixo' | 'normal' | 'completo';

/** Status de estoque para dashboard (componentes React) */
export type StockStatusDashboard = 'critical' | 'low' | 'high' | 'normal';

/** Tipo de alerta gerado pelo trigger de estoque */
export type StockAlertType = 'sem_estoque' | 'critico' | 'baixo';

/** Resultado do status de estoque no formulário de movimentação */
export interface StockStatusFormResult {
  label: string;
  variant: 'destructive' | 'secondary' | 'default';
  percentage: number;
}

/** Item processado pela IA com informações de matching */
export interface MatchResult {
  matchConfidence: number;
  isLowConfidence: boolean;
  isLocked: boolean;
}

/** Item com flag de baixa confiança */
export interface ItemWithConfidence {
  isLowConfidence?: boolean;
}

// ============================================================
// Constantes
// ============================================================

/** Threshold mínimo de similaridade para considerar match válido */
export const MATCH_THRESHOLD = 0.72;

// ============================================================
// Status de Estoque — Compras (view SQL: view_compras_analise)
// ============================================================

/**
 * Calcula status de estoque para decisões de compra.
 * Replica a lógica da view SQL `view_compras_analise`.
 *
 * Prioridade:
 * 1. sem_estoque: quantidade_atual <= 0
 * 2. critico: quantidade_atual <= (quantidade_minima * 0.5)
 * 3. baixo: quantidade_atual <= quantidade_minima
 * 4. completo: quantidade_atual >= quantidade_maxima
 * 5. normal: demais casos
 */
export function getStockStatusPurchasing(
  quantidadeAtual: number,
  quantidadeMinima: number,
  quantidadeMaxima: number
): StockStatusPurchasing {
  if (quantidadeAtual <= 0) return 'sem_estoque';
  if (quantidadeAtual <= quantidadeMinima * 0.5) return 'critico';
  if (quantidadeAtual <= quantidadeMinima) return 'baixo';
  if (quantidadeAtual >= quantidadeMaxima) return 'completo';
  return 'normal';
}

/**
 * Calcula a prioridade de compra (1 = mais urgente).
 * Replica a lógica da view SQL `view_compras_analise`.
 */
export function getPurchasePriority(
  quantidadeAtual: number,
  quantidadeMinima: number
): number {
  if (quantidadeAtual <= 0) return 1;
  if (quantidadeAtual <= quantidadeMinima * 0.5) return 2;
  if (quantidadeAtual <= quantidadeMinima) return 3;
  return 4;
}

/**
 * Calcula a quantidade sugerida para reposição.
 * Replica a lógica da view SQL `view_compras_analise`.
 */
export function getSuggestedQuantity(
  quantidadeAtual: number,
  quantidadeMaxima: number
): number {
  if (quantidadeMaxima > quantidadeAtual) {
    return quantidadeMaxima - quantidadeAtual;
  }
  return 0;
}

// ============================================================
// Status de Estoque — Dashboard (InventoryList / ExpandedInventoryList)
// ============================================================

/**
 * Calcula percentual de estoque baseado no máximo.
 */
export function getStockPercentage(current: number, max: number): number {
  return (current / max) * 100;
}

/**
 * Determina status de estoque para visualização no dashboard.
 * Lógica dos componentes InventoryList e ExpandedInventoryList.
 */
export function getStockStatusDashboard(
  current: number,
  min: number,
  max: number
): StockStatusDashboard {
  const percentage = getStockPercentage(current, max);
  if (current <= min) return 'critical';
  if (percentage <= 30) return 'low';
  if (percentage >= 80) return 'high';
  return 'normal';
}

/**
 * Retorna classe CSS de cor de texto para o status.
 */
export function getStatusColor(status: StockStatusDashboard): string {
  switch (status) {
    case 'critical': return 'text-destructive';
    case 'low': return 'text-warning';
    case 'high': return 'text-success';
    default: return 'text-foreground';
  }
}

/**
 * Retorna classe CSS de cor de fundo da barra de progresso.
 */
export function getProgressColor(status: StockStatusDashboard): string {
  switch (status) {
    case 'critical': return 'bg-destructive';
    case 'low': return 'bg-warning';
    case 'high': return 'bg-success';
    default: return 'bg-primary';
  }
}

/**
 * Retorna label traduzido para o status de estoque do dashboard.
 */
export function getStatusLabel(status: StockStatusDashboard): string {
  switch (status) {
    case 'critical': return 'Crítico';
    case 'low': return 'Baixo';
    case 'high': return 'Alto';
    default: return 'Normal';
  }
}

// ============================================================
// Status de Estoque — Formulário de Movimentação (RealMovementForm)
// ============================================================

/**
 * Calcula status de estoque com label e variante para badges.
 * Lógica do componente RealMovementForm.
 */
export function getStockStatusForm(
  atual: number,
  minimo: number,
  maximo: number
): StockStatusFormResult {
  const percentage = (atual / maximo) * 100;
  if (atual === 0) return { label: 'Sem estoque', variant: 'destructive', percentage: 0 };
  if (atual <= minimo) return { label: 'Estoque baixo', variant: 'secondary', percentage };
  return { label: 'Estoque normal', variant: 'default', percentage };
}

// ============================================================
// Alertas de Estoque — Trigger SQL (atualizar_estoque_e_alertas)
// ============================================================

/**
 * Determina o tipo de alerta de estoque.
 * Replica a lógica do trigger SQL `atualizar_estoque_e_alertas()`.
 * Retorna null se nenhum alerta é necessário.
 */
export function getStockAlertType(
  estoqueAtual: number,
  estoqueMinimo: number
): StockAlertType | null {
  if (estoqueAtual <= 0) return 'sem_estoque';
  if (estoqueAtual <= estoqueMinimo * 0.5) return 'critico';
  if (estoqueAtual <= estoqueMinimo) return 'baixo';
  return null;
}

// ============================================================
// Ghost Items (Requisicao.tsx)
// ============================================================

/**
 * Determina se um item é "fantasma" (estoque suficiente, sem necessidade de reposição).
 * Um item fantasma tem quantidade solicitada igual a zero.
 */
export function isGhostItem(requested: number): boolean {
  return requested === 0;
}

/**
 * Calcula a opacidade do item baseada no estado de ghost e arraste.
 */
export function getItemOpacity(isGhost: boolean, isDragging: boolean): number {
  if (isDragging) return 0.5;
  if (isGhost) return 0.6;
  return 1;
}

/**
 * Determina as classes CSS de borda para um item de requisição.
 */
export function getItemBorderClass(isGhost: boolean, isSeparated: boolean): string {
  if (isGhost) return 'border-dashed border-muted';
  if (isSeparated) return 'border-green-500/50';
  return 'border-border/50';
}

/**
 * Determina a classe CSS de fundo para um item de requisição.
 */
export function getItemBgClass(isGhost: boolean, isSeparated: boolean): string {
  if (isGhost) return 'bg-muted/30';
  if (isSeparated) return 'bg-green-50/50 dark:bg-green-900/20';
  return 'bg-background/50';
}

// ============================================================
// Match Confidence (Requisicao.tsx)
// ============================================================

/**
 * Determina se um score de match é considerado baixa confiança.
 */
export function isLowConfidenceMatch(
  score: number,
  threshold: number = MATCH_THRESHOLD
): boolean {
  return score < threshold;
}

/**
 * Resolve o resultado de matching de um item com base no score de similaridade.
 *
 * Se o score >= threshold: match válido (locked, alta confiança)
 * Se o score < threshold: match inválido (não locked, baixa confiança)
 */
export function resolveMatchResult(
  matchScore: number,
  threshold: number = MATCH_THRESHOLD
): MatchResult {
  if (matchScore >= threshold) {
    return {
      matchConfidence: matchScore,
      isLowConfidence: false,
      isLocked: true
    };
  }
  return {
    matchConfidence: matchScore,
    isLowConfidence: true,
    isLocked: false
  };
}

/**
 * Verifica se há itens com baixa confiança não resolvidos na lista.
 * Usado como validação antes de salvar/enviar a requisição.
 */
export function hasUnresolvedLowConfidenceItems(items: ItemWithConfidence[]): boolean {
  return items.some(i => i.isLowConfidence);
}

/**
 * Cria resultado de match para seleção manual do catálogo.
 * Quando o usuário seleciona manualmente, a confiança é 100%.
 */
export function createManualMatchResult(): MatchResult {
  return {
    matchConfidence: 1,
    isLowConfidence: false,
    isLocked: true
  };
}

/**
 * Cria resultado de match para correspondência exata (strict match).
 * Score 1.0, confiança máxima.
 */
export function createStrictMatchResult(): MatchResult {
  return {
    matchConfidence: 1,
    isLowConfidence: false,
    isLocked: true
  };
}

