import { useState, useMemo } from 'react';
import { Button } from '@/shared/ui/button';
import {
  Dialog,
  DialogContent,
  DialogHeader,
  DialogTitle,
  DialogTrigger,
} from '@/shared/ui/dialog';
import { Input } from '@/shared/ui/input';
import { Search, Bot, TrendingUp, AlertCircle, Calendar } from 'lucide-react';
import { useProductSalesData, ProductAnalysis } from '@/features/produtos';
import {
  AreaChart,
  Area,
  XAxis,
  YAxis,
  Tooltip,
  ResponsiveContainer,
} from 'recharts';
import { Badge } from '@/shared/ui/badge';
import { parseISO, format } from 'date-fns';

interface DemandConsultantProps {
  storeName: string;
  className?: string;
}

export function DemandConsultant({
  storeName,
  className,
}: DemandConsultantProps) {
  const [isOpen, setIsOpen] = useState(false);
  const [searchTerm, setSearchTerm] = useState('');

  // We analyze based on the current day of the week by default for quick insights
  const currentWeekday = new Date().toLocaleDateString('pt-BR', {
    weekday: 'long',
  });
  const { products } = useProductSalesData({
    selectedStore: storeName,
    targetWeekday: currentWeekday,
  });

  const filteredProducts = useMemo(() => {
    if (!searchTerm) return [];
    const lower = searchTerm.toLowerCase();
    return products
      .filter(
        (p) =>
          p.name.toLowerCase().includes(lower) ||
          p.code.toLowerCase().includes(lower),
      )
      .slice(0, 5); // Limit to 5 results for cleaner UI
  }, [products, searchTerm]);

  return (
    <Dialog open={isOpen} onOpenChange={setIsOpen}>
      <DialogTrigger asChild>
        <Button
          variant="outline"
          size="sm"
          className={`gap-2 rounded-full border-primary/20 bg-background/50 backdrop-blur hover:bg-primary/10 hover:text-primary transition-all ${className}`}
        >
          <Bot className="w-4 h-4 text-primary" />
          <span className="hidden sm:inline">Consultor de Demanda</span>
        </Button>
      </DialogTrigger>
      <DialogContent data-mia-modal="consultor-de-demanda-store-name" className="max-w-2xl">
        <DialogHeader>
          <DialogTitle className="flex items-center gap-2">
            <Bot className="w-5 h-5 text-primary" />
            Consultor de Demanda - {storeName}
          </DialogTitle>
        </DialogHeader>

        <div className="space-y-6 py-4">
          <div className="relative">
            <Search className="absolute left-3 top-1/2 -translate-y-1/2 w-4 h-4 text-muted-foreground" />
            <Input data-mia-field="search_term"
              placeholder="Digite o nome do produto para ver a demanda..."
              value={searchTerm}
              onChange={(e) => setSearchTerm(e.target.value)}
              className="pl-9 h-12 text-lg"
              autoFocus
            />
          </div>

          <div className="space-y-4 min-h-[300px]">
            {!searchTerm && (
              <div className="flex flex-col items-center justify-center h-48 text-muted-foreground text-center p-4">
                <Bot className="w-12 h-12 mb-4 text-primary/20" />
                <p>
                  Digite um produto acima para consultar
                  <br />o histórico de vendas e sugestões da IA.
                </p>
              </div>
            )}

            {filteredProducts.length > 0 && (
              <div className="space-y-4 animate-in fade-in slide-in-from-bottom-4">
                {filteredProducts.map((product) => (
                  <ProductInsightCard
                    key={product.id}
                    product={product}
                    targetWeekday={currentWeekday}
                  />
                ))}
              </div>
            )}

            {searchTerm && filteredProducts.length === 0 && (
              <div className="text-center py-8 text-muted-foreground">
                Nenhum produto encontrado com "{searchTerm}"
              </div>
            )}
          </div>
        </div>
      </DialogContent>
    </Dialog>
  );
}

function ProductInsightCard({
  product,
  targetWeekday,
}: {
  product: ProductAnalysis;
  targetWeekday: string;
}) {
  const stats = product.stats[targetWeekday];
  const historyData = product.salesHistory
    .slice(0, 14)
    .reverse()
    .map((s) => ({
      date: format(parseISO(s.date), 'dd/MM'),
      qtd: s.quantity,
    }));

  return (
    <div className="border rounded-xl p-4 bg-card hover:bg-accent/5 transition-colors">
      <div className="flex items-start justify-between mb-4">
        <div>
          <h4 className="font-bold text-lg">{product.name}</h4>
          <span className="text-xs text-muted-foreground uppercase">
            {product.category}
          </span>
        </div>
        <div className="text-right">
          <div className="text-sm text-muted-foreground">Sugestão IA</div>
          <div className="text-2xl font-bold text-primary">
            {product.suggestion} un
          </div>
        </div>
      </div>

      <div className="grid grid-cols-2 gap-4 mb-4">
        <div className="bg-secondary/20 rounded-lg p-3">
          <div className="flex items-center gap-2 mb-1">
            <TrendingUp className="w-3 h-3 text-muted-foreground" />
            <span className="text-xs font-medium text-muted-foreground">
              Média ({targetWeekday.split('-')[0]})
            </span>
          </div>
          <span className="text-lg font-bold">
            {stats?.avg.toFixed(1) || 0}
          </span>
        </div>
        <div className="bg-secondary/20 rounded-lg p-3">
          <div className="flex items-center gap-2 mb-1">
            <Calendar className="w-3 h-3 text-muted-foreground" />
            <span className="text-xs font-medium text-muted-foreground">
              Últimos 14 dias
            </span>
          </div>
          <span className="text-lg font-bold">
            {product.periodAvg.toFixed(1)}/dia
          </span>
        </div>
      </div>

      <div className="h-24 w-full">
        <ResponsiveContainer width="100%" height="100%">
          <AreaChart data={historyData}>
            <defs>
              <linearGradient
                id={`grad-${product.id}`}
                x1="0"
                y1="0"
                x2="0"
                y2="1"
              >
                <stop offset="5%" stopColor="#8884d8" stopOpacity={0.3} />
                <stop offset="95%" stopColor="#8884d8" stopOpacity={0} />
              </linearGradient>
            </defs>
            <Tooltip
              contentStyle={{
                borderRadius: '8px',
                border: 'none',
                boxShadow: '0 4px 12px rgba(0,0,0,0.1)',
              }}
              cursor={{ stroke: '#8884d8', strokeWidth: 1 }}
            />
            <Area
              type="monotone"
              dataKey="qtd"
              stroke="#8884d8"
              fillOpacity={1}
              fill={`url(#grad-${product.id})`}
            />
          </AreaChart>
        </ResponsiveContainer>
      </div>
    </div>
  );
}

