112	
113	  useEffect(() => {
114	    loadStores();
115	    // eslint-disable-next-line react-hooks/exhaustive-deps
116	  }, []);
117	
118	  const loadStores = async () => {
119	    const { data } = await supabase
120	      .from('lojas')
121	      .select('id, nome')
122	      .eq('ativo', true)
123	      .order('id');
124	    if (data) {
125	      setStores(data);
