133	    }
134	  };
135	
136	  // Calculate Target Days Array
137	  const targetDays = useMemo(() => {
138	    if (!selectedDay) return [];
139	    const startIndex = days.indexOf(selectedDay);
140	    if (startIndex === -1) return [];
141	
142	    const result = [];
143	    for (let i = 0; i < coverageDays; i++) {
144	      const index = (startIndex + i) % 7;
145	      result.push(days[index]);
146	    }
147	    return result;
148	    // eslint-disable-next-line react-hooks/exhaustive-deps
149	  }, [selectedDay, coverageDays]);
150	
151	  useEffect(() => {
152	    if (step === 'products' && sectors.length === 0) {
153	      loadProducts();
154	    }
155	    // eslint-disable-next-line react-hooks/exhaustive-deps
156	  }, [step]);
157	
158	  const loadProducts = async () => {
159	    setLoadingProducts(true);
160	    try {
161	      // Fetch Sectors
162	      const { data: sectorsTable, error: sectorError } = await supabase
163	        .from('setores')
164	        .select('nome')
165	        .eq('ativo', true)
166	        .order('nome');
167	      
168	      if (sectorError) throw sectorError;
169	
170	      // Fetch Products
171	      const { data: prods, error: prodError } = await supabase
172	        .from('produtos_master')
173	        .select('id, nome, setor, codigo_interno')
174	        .eq('ativo', true)
175	        .order('nome');
176	
177	      if (prodError) throw prodError;
178	
179	      // Build Tree
