182	      
183	      // Initialize with all sectors from the table to ensure they appear
184	      sectorsTable?.forEach(s => {
185	        if (!sectorMap[s.nome]) sectorMap[s.nome] = [];
186	      });
187	
188	      prods.forEach((prod) => {
189	        const setor = prod.setor || 'Outros';
190	        if (!sectorMap[setor]) sectorMap[setor] = [];
191	
192	        sectorMap[setor].push({
193	          ...prod,
194	          checked: true
195	        });
196	      });
197	
198	      const sectorNodes: SectorNode[] = Object.entries(sectorMap)
199	        .sort((a, b) => a[0].localeCompare(b[0]))
200	        .map(([name, products]) => ({
201	          name,
202	          products,
203	          checked: products.length > 0 && products.every(p => p.checked),
204	        }));
205	
206	      setSectors(sectorNodes);
207	    } catch (error) {
208	      handleError(error, { domain: 'requisicoes', operation: 'loadProducts', showToast: false });
209	      toast.error('Erro ao carregar produtos.');
210	    } finally {
211	      setLoadingProducts(false);
212	    }
213	  };
214	
215	  // Toggle Logic
216	  const toggleProduct = (sectorName: string, prodId: number) => {
217	    setSectors((prev) =>
218	      prev.map((s) => {
219	        if (s.name !== sectorName) return s;
