221	          p.id === prodId ? { ...p, checked: !p.checked } : p,
222	        );
223	        const allChecked = newProds.every((p) => p.checked);
224	        return { ...s, products: newProds, checked: allChecked };
225	      }),
226	    );
227	  };
228	
229	  const toggleSector = (sectorName: string) => {
