231	      prev.map((s) => {
232	        if (s.name !== sectorName) return s;
233	        const newChecked = !s.checked;
234	        const newProds = s.products.map((p) => ({ ...p, checked: newChecked }));
235	        return { ...s, products: newProds, checked: newChecked };
236	      }),
237	    );
238	  };
239	
240	  // Filter Logic
