433	                  ) : (
434	                    <span className="text-muted-foreground italic">
435	                      Selecione um dia de início...
436	                    </span>
437	                  )}
438	                </div>
439	              </div>
440	            </div>
441	
442	            <Button
443	              size="lg"
444	              className="w-full text-lg h-14 shadow-lg hover:shadow-xl transition-all"
445	              onClick={() => setStep('products')}
