450	            </Button>
451	          </CardContent>
452	        </Card>
453	        <SalesMappingModal
454	          isOpen={isMatchModalOpen}
455	          onClose={() => setIsMatchModalOpen(false)}
456	        />
457	      </div>
458	    );
459	  }
460	
461	  // Step 2: Product Selection
462	  const currentStoreName =
463	    stores.find((s) => s.id === selectedStoreId)?.nome || 'Loja';
464	
465	  return (
466	    <div className="container md:max-w-4xl max-w-full mx-auto py-8 md:py-12 px-4 animate-in fade-in slide-in-from-right-8 duration-500">
467	      <div className="flex items-center justify-between mb-6">
468	        <Button
469	          variant="ghost"
470	          onClick={() => setStep('day')}
471	          className="gap-2 hover:bg-transparent hover:text-primary pl-0"
472	        >
473	          <ArrowLeft className="w-4 h-4" />
474	          Voltar para seleção de dia
475	        </Button>
476	
477	        {selectedStoreId && <DemandConsultant storeName={currentStoreName} />}
478	
479	        {/* Match Configuration Button */}
480	        <div className="flex items-center gap-2 ml-4 border-l pl-4">
481	          <Button
482	            variant="ghost"
483	            size="icon"
484	            onClick={() => setIsMatchModalOpen(true)}
485	            className="text-muted-foreground hover:text-primary"
486	            title="Configurar Match de Vendas"
487	          >
488	            <LinkIcon className="h-5 w-5" />
489	          </Button>
490	        </div>
491	      </div>
492	
493	      <Card className="border-2 border-primary/10 shadow-lg flex flex-col h-[80vh] md:h-auto">
494	        <CardHeader className="bg-muted/30 pb-4 pt-6 shrink-0">
495	          <div className="flex flex-col md:flex-row md:items-center justify-between gap-4">
496	            <div className="flex items-center gap-3">
497	              <div className="p-2 bg-primary/10 rounded-lg">
498	                <Layers className="w-6 h-6 text-primary" />
