531	                  <Accordion
532	                    type="multiple"
533	                    defaultValue={filteredSectors.map((s) => s.name)}
534	                    className="space-y-4"
535	                  >
536	                    {filteredSectors.map((sector) => (
537	                      <AccordionItem
538	                        value={sector.name}
539	                        key={sector.name}
540	                        className="border-none bg-white rounded-lg shadow-sm px-4"
