import { useState, useEffect, useMemo } from 'react';
import { Button } from '@/shared/ui/button';
import {
  Card,
  CardContent,
  CardDescription,
  CardHeader,
  CardTitle,
} from '@/shared/ui/card';
import {
  Bot,
  Calendar,
  ArrowRight,
  ArrowLeft,
  Loader2,
  Play,
  Layers,
  Search,
  CheckCircle2,
  Link as LinkIcon,
} from 'lucide-react';
import { Label } from '@/shared/ui/label';
import { Input } from '@/shared/ui/input';
import { Switch } from '@/shared/ui/switch';
import { ScrollArea } from '@/shared/ui/scroll-area';
import {
  Accordion,
  AccordionContent,
  AccordionItem,
  AccordionTrigger,
} from '@/shared/ui/accordion';
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from '@/shared/ui/select';
import { supabase } from '@/integrations/supabase/client';
import { toast } from 'sonner';
import { Badge } from '@/shared/ui/badge';
import { DemandConsultant } from '@/features/requisicoes/ui/DemandConsultant';
import { format } from 'date-fns';
import { ptBR } from 'date-fns/locale';
import { SalesMappingModal } from './SalesMappingModal';
import { handleError } from '@/shared/lib/error-handler';

interface AutoRequisitionWizardProps {
  onBack: () => void;
  onConfirm: (
    storeId: number,
    targetDays: string[],
    selectedProducts: any[],
    storeName: string,
  ) => void;
  isLoading: boolean;
  loadingWordsIndex: number;
  loadingWords: string[];
  defaultStoreName: string;
}

interface ProductNode {
  id: number;
  nome: string;
  setor: string;
  codigo_interno: number;
  checked: boolean;
}

interface Store {
  id: number;
  nome: string;
}

interface SectorNode {
  name: string;
  products: ProductNode[];
  checked: boolean; // if all products in sector checked
}

export function AutoRequisitionWizard({
  onBack,
  onConfirm,
  isLoading,
  loadingWordsIndex,
  loadingWords,
  defaultStoreName,
}: AutoRequisitionWizardProps) {
  const [step, setStep] = useState<'day' | 'products'>('day');
  const [isMatchModalOpen, setIsMatchModalOpen] = useState(false);

  // Store & Date State
  const [stores, setStores] = useState<Store[]>([]);
  const [selectedStoreId, setSelectedStoreId] = useState<number | null>(null);
  const [selectedDay, setSelectedDay] = useState<string>('');
  const [coverageDays, setCoverageDays] = useState<number>(1);

  // Product Selection State
  const [loadingProducts, setLoadingProducts] = useState(false);
  const [sectors, setSectors] = useState<SectorNode[]>([]);
  const [searchTerm, setSearchTerm] = useState('');

  const days = [
    'Segunda-feira',
    'Terça-feira',
    'Quarta-feira',
    'Quinta-feira',
    'Sexta-feira',
    'Sábado',
    'Domingo',
  ];

  useEffect(() => {
    loadStores();
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);

  const loadStores = async () => {
    const { data } = await supabase
      .from('lojas')
      .select('id, nome')
      .eq('ativo', true)
      .order('id');
    if (data) {
      setStores(data);
      // Try to match default store
      if (defaultStoreName) {
        const match = data.find((s) =>
          s.nome.toLowerCase().includes(defaultStoreName.toLowerCase()),
        );
        if (match) setSelectedStoreId(match.id);
      }
    }
  };

  // Calculate Target Days Array
  const targetDays = useMemo(() => {
    if (!selectedDay) return [];
    const startIndex = days.indexOf(selectedDay);
    if (startIndex === -1) return [];

    const result = [];
    for (let i = 0; i < coverageDays; i++) {
      const index = (startIndex + i) % 7;
      result.push(days[index]);
    }
    return result;
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [selectedDay, coverageDays]);

  useEffect(() => {
    if (step === 'products' && sectors.length === 0) {
      loadProducts();
    }
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [step]);

  const loadProducts = async () => {
    setLoadingProducts(true);
    try {
      // Fetch Sectors
      const { data: sectorsTable, error: sectorError } = await supabase
        .from('setores')
        .select('nome')
        .eq('ativo', true)
        .order('nome');

      if (sectorError) throw sectorError;

      // Fetch Products
      const { data: prods, error: prodError } = await supabase
        .from('produtos_master')
        .select('id, nome, setor, codigo_interno')
        .eq('ativo', true)
        .order('nome');

      if (prodError) throw prodError;

      // Build Tree
      // Primary grouping: Sector
      const sectorMap: Record<string, ProductNode[]> = {};

      // Initialize with all sectors from the table to ensure they appear
      sectorsTable?.forEach(s => {
        if (!sectorMap[s.nome]) sectorMap[s.nome] = [];
      });

      prods.forEach((prod) => {
        const setor = prod.setor || 'Outros';
        if (!sectorMap[setor]) sectorMap[setor] = [];

        sectorMap[setor].push({
          ...prod,
          checked: true
        });
      });

      const sectorNodes: SectorNode[] = Object.entries(sectorMap)
        .sort((a, b) => a[0].localeCompare(b[0]))
        .map(([name, products]) => ({
          name,
          products,
          checked: products.length > 0 && products.every(p => p.checked),
        }));

      setSectors(sectorNodes);
    } catch (error) {
      handleError(error, { domain: 'requisicoes', operation: 'loadProducts', showToast: false });
      toast.error('Erro ao carregar produtos.');
    } finally {
      setLoadingProducts(false);
    }
  };

  // Toggle Logic
  const toggleProduct = (sectorName: string, prodId: number) => {
    setSectors((prev) =>
      prev.map((s) => {
        if (s.name !== sectorName) return s;
        const newProds = s.products.map((p) =>
          p.id === prodId ? { ...p, checked: !p.checked } : p,
        );
        const allChecked = newProds.every((p) => p.checked);
        return { ...s, products: newProds, checked: allChecked };
      }),
    );
  };

  const toggleSector = (sectorName: string) => {
    setSectors((prev) =>
      prev.map((s) => {
        if (s.name !== sectorName) return s;
        const newChecked = !s.checked;
        const newProds = s.products.map((p) => ({ ...p, checked: newChecked }));
        return { ...s, products: newProds, checked: newChecked };
      }),
    );
  };

  // Filter Logic
  const filteredSectors = useMemo(() => {
    if (!searchTerm) return sectors;
    const lower = searchTerm.toLowerCase();

    return sectors
      .map((s) => {
        const matchingProds = s.products.filter((p) =>
          p.nome.toLowerCase().includes(lower),
        );
        if (matchingProds.length > 0) {
          return { ...s, products: matchingProds };
        }
        return null;
      })
      .filter(Boolean) as SectorNode[];
  }, [sectors, searchTerm]);

  const totalSelected = useMemo(() => {
    return sectors.reduce(
      (acc, s) => acc + s.products.filter((p) => p.checked).length,
      0,
    );
  }, [sectors]);

  const handleFinalConfirm = () => {
    const selectedProducts = sectors.flatMap((s) =>
      s.products
        .filter((p) => p.checked)
        .map((p) => ({
          id: p.id,
          name: p.nome,
          nome: p.nome,
          code: p.codigo_interno,
        })),
    );
    const storeName =
      stores.find((s) => s.id === Number(selectedStoreId))?.nome || 'Loja';
    onConfirm(Number(selectedStoreId), targetDays, selectedProducts, storeName);
  };

  if (isLoading) {
    return (
      <div className="fixed inset-0 z-50 bg-background/95 backdrop-blur-sm flex flex-col items-center justify-center p-4">
        <div className="w-full max-w-md space-y-8 text-center animate-in fade-in zoom-in duration-500">
          <div className="relative mx-auto w-24 h-24 mb-8">
            <div className="absolute inset-0 bg-primary/20 rounded-full animate-ping opacity-75"></div>
            <div className="relative bg-background p-4 rounded-full border-2 border-primary shadow-xl flex items-center justify-center h-full w-full">
              <Bot className="h-10 w-10 text-primary animate-bounce lg:h-12 lg:w-12" />
            </div>
          </div>

          <div className="space-y-4">
            <h2 className="text-2xl font-bold tracking-tight lg:text-3xl">
              Analisando{' '}
              {stores.find((s) => s.id.toString() === selectedStoreId)?.nome ||
                'Loja'}
            </h2>

            <div className="h-16 flex items-center justify-center">
              <span className="text-xl text-muted-foreground animate-pulse font-medium">
                {loadingWords[loadingWordsIndex]}
              </span>
            </div>

            <div className="flex justify-center gap-2 mt-4">
              <div className="w-2 h-2 bg-primary rounded-full animate-bounce [animation-delay:-0.3s]"></div>
              <div className="w-2 h-2 bg-primary rounded-full animate-bounce [animation-delay:-0.15s]"></div>
              <div className="w-2 h-2 bg-primary rounded-full animate-bounce"></div>
            </div>
          </div>
        </div>
      </div>
    );
  }

  // Step 1: Day Selection
  if (step === 'day') {
    return (
      <div className="container max-w-2xl mx-auto py-12 px-4 animate-in fade-in slide-in-from-bottom-4 duration-500">
        <Button data-mia-action="on-back"
          variant="ghost"
          onClick={onBack}
          className="mb-6 gap-2 hover:bg-transparent hover:text-primary pl-0"
        >
          <ArrowLeft className="w-4 h-4" />
          Voltar para lista
        </Button>

        <Card className="border-2 border-primary/10 shadow-lg">
          <CardHeader className="bg-muted/30 pb-8 pt-6">
            <div className="flex items-center justify-between mb-2">
              <div className="flex items-center gap-3">
                <div className="p-2 bg-primary/10 rounded-lg">
                  <Bot className="w-6 h-6 text-primary" />
                </div>
                <CardTitle className="text-2xl">
                  Assistente de Requisição
                </CardTitle>
              </div>
              <Button
                variant="ghost"
                size="icon"
                onClick={() => setIsMatchModalOpen(true)}
                className="text-muted-foreground hover:text-primary"
                title="Configurar Match de Vendas"
              >
                <LinkIcon className="h-5 w-5" />
              </Button>
            </div>
            <CardDescription className="text-base">
              Selecione a loja e o período. A IA vai analisar o padrão de
              consumo específico para cada dia selecionado.
            </CardDescription>
          </CardHeader>

          <CardContent className="space-y-8 pt-8 px-6 pb-8">
            {/* Store Selector */}
            <div className="space-y-4">
              <Label className="text-base font-semibold">1. Qual Loja?</Label>
              <Select
                value={selectedStoreId?.toString()}
                onValueChange={(v) => setSelectedStoreId(Number(v))}
              >
                <SelectTrigger className="h-12 text-lg">
                  <SelectValue placeholder="Selecione a loja..." />
                </SelectTrigger>
                <SelectContent>
                  {stores.map((store) => (
                    <SelectItem key={store.id} value={store.id.toString()}>
                      {store.nome}
                    </SelectItem>
                  ))}
                </SelectContent>
              </Select>
            </div>

            <div className="space-y-4">
              <Label className="text-base font-semibold">
                2. Dia de Início da Análise
              </Label>
              <div className="grid grid-cols-2 md:grid-cols-4 gap-3">
                {days.map((day) => (
                  <Button
                    key={day}
                    variant={selectedDay === day ? 'default' : 'outline'}
                    className={`h-12 w-full transition-all ${selectedDay === day ? 'ring-2 ring-primary ring-offset-2' : ''}`}
                    onClick={() => setSelectedDay(day)}
                  >
                    {day}
                  </Button>
                ))}
              </div>
            </div>

            <div className="space-y-4">
              <Label className="text-base font-semibold">
                3. Duração do Estoque (Quantos dias sem entrega?)
              </Label>
              <div className="grid grid-cols-2 md:grid-cols-4 gap-3">
                {[
                  { d: 1, label: '1 Dia (Padrão)' },
                  { d: 2, label: '2 Dias' },
                  { d: 3, label: '3 Dias' },
                  { d: 4, label: '4 Dias' },
                ].map((opt) => (
                  <Button
                    key={opt.d}
                    variant={coverageDays === opt.d ? 'default' : 'outline'}
                    className={`h-12 w-full transition-all ${coverageDays === opt.d ? 'ring-2 ring-primary ring-offset-2' : 'bg-transparent'}`}
                    onClick={() => setCoverageDays(opt.d)}
                  >
                    {opt.label}
                  </Button>
                ))}
              </div>

              {/* Dynamic Context Feedback */}
              <div className="bg-primary/5 border border-primary/20 rounded-md p-4 text-sm mt-4">
                <span className="font-semibold text-primary block mb-1">
                  A IA vai considerar o consumo de:
                </span>
                <div className="flex flex-wrap gap-2 mt-2">
                  {targetDays.length > 0 ? (
                    targetDays.map((d, i) => (
                      <Badge
                        key={i}
                        variant="secondary"
                        className="text-sm px-2 py-1 bg-white border-primary/20 shadow-sm"
                      >
                        {d}
                      </Badge>
                    ))
                  ) : (
                    <span className="text-muted-foreground italic">
                      Selecione um dia de início...
                    </span>
                  )}
                </div>
              </div>
            </div>

            <Button
              size="lg"
              className="w-full text-lg h-14 shadow-lg hover:shadow-xl transition-all"
              onClick={() => setStep('products')}
              disabled={!selectedDay || !selectedStoreId}
            >
              <ArrowRight className="w-5 h-5 mr-2" />
              Continuar: Selecionar Produtos
            </Button>
          </CardContent>
        </Card>
        <SalesMappingModal
          isOpen={isMatchModalOpen}
          onClose={() => setIsMatchModalOpen(false)}
        />
      </div>
    );
  }

  // Step 2: Product Selection
  const currentStoreName =
    stores.find((s) => s.id === selectedStoreId)?.nome || 'Loja';

  return (
    <div className="container md:max-w-4xl max-w-full mx-auto py-8 md:py-12 px-4 animate-in fade-in slide-in-from-right-8 duration-500">
      <div className="flex items-center justify-between mb-6">
        <Button
          variant="ghost"
          onClick={() => setStep('day')}
          className="gap-2 hover:bg-transparent hover:text-primary pl-0"
        >
          <ArrowLeft className="w-4 h-4" />
          Voltar para seleção de dia
        </Button>

        {selectedStoreId && <DemandConsultant storeName={currentStoreName} />}

        {/* Match Configuration Button */}
        <div className="flex items-center gap-2 ml-4 border-l pl-4">
          <Button
            variant="ghost"
            size="icon"
            onClick={() => setIsMatchModalOpen(true)}
            className="text-muted-foreground hover:text-primary"
            title="Configurar Match de Vendas"
          >
            <LinkIcon className="h-5 w-5" />
          </Button>
        </div>
      </div>

      <Card className="border-2 border-primary/10 shadow-lg flex flex-col h-[80vh] md:h-auto">
        <CardHeader className="bg-muted/30 pb-4 pt-6 shrink-0">
          <div className="flex flex-col md:flex-row md:items-center justify-between gap-4">
            <div className="flex items-center gap-3">
              <div className="p-2 bg-primary/10 rounded-lg">
                <Layers className="w-6 h-6 text-primary" />
              </div>
              <div>
                <CardTitle className="text-xl md:text-2xl">
                  O que analisar para {currentStoreName}?
                </CardTitle>
                <CardDescription>
                  Selecione os produtos por setor para a IA calcular.
                </CardDescription>
              </div>
            </div>
            <div className="flex items-center gap-2 bg-background border p-2 rounded-lg w-full md:w-auto">
              <Search className="h-4 w-4 text-muted-foreground" />
              <input
                className="bg-transparent border-none text-sm focus:outline-none w-full md:w-48"
                placeholder="Filtrar produtos..."
                value={searchTerm}
                onChange={(e) => setSearchTerm(e.target.value)}
              />
            </div>
          </div>
        </CardHeader>

        <CardContent className="p-0 flex-1 overflow-hidden flex flex-col">
          {loadingProducts ? (
            <div className="h-64 flex items-center justify-center">
              <Loader2 className="h-8 w-8 animate-spin text-primary" />
              <span className="ml-2">Carregando catálogo...</span>
            </div>
          ) : (
            <div className="flex-1 overflow-hidden bg-slate-50/50 relative">
              <ScrollArea className="h-full">
                <div className="p-4 space-y-4 pb-24">
                  <Accordion
                    type="multiple"
                    defaultValue={filteredSectors.map((s) => s.name)}
                    className="space-y-4"
                  >
                    {filteredSectors.map((sector) => (
                      <AccordionItem
                        value={sector.name}
                        key={sector.name}
                        className="border-none bg-white rounded-lg shadow-sm px-4"
                      >
                        <AccordionTrigger className="hover:no-underline py-3">
                          <div className="flex items-center justify-between w-full pr-4">
                            <div className="flex items-center gap-2">
                              <span className="font-semibold text-lg">
                                {sector.name}
                              </span>
                              <span className="text-xs text-muted-foreground font-normal ml-2">
                                ({sector.products.length} itens)
                              </span>
                            </div>
                            <div
                              className="flex items-center gap-2"
                              onClick={(e) => e.stopPropagation()}
                            >
                              <Switch
                                checked={sector.checked}
                                onCheckedChange={() =>
                                  toggleSector(sector.name)
                                }
                              />
                            </div>
                          </div>
                        </AccordionTrigger>
                        <AccordionContent className="pt-2 pb-4">
                          <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-2 pl-4 border-l-2 border-slate-200">
                            {sector.products.map((prod) => (
                              <div
                                key={prod.id}
                                className={`text-sm py-1.5 px-2 rounded cursor-pointer transition-colors flex items-center justify-between ${prod.checked ? 'bg-primary/10 text-primary font-bold shadow-sm border border-primary/20' : 'hover:bg-slate-100 text-muted-foreground'}`}
                                onClick={() =>
                                  toggleProduct(sector.name, prod.id)
                                }
                              >
                                <span>{prod.nome}</span>
                                {prod.checked && (
                                  <CheckCircle2 className="h-4 w-4 text-primary" />
                                )}
                              </div>
                            ))}
                          </div>
                        </AccordionContent>
                      </AccordionItem>
                    ))}
                  </Accordion>
                </div>
              </ScrollArea>

              {/* Floating Footer */}
              <div className="absolute bottom-0 left-0 right-0 p-4 bg-white/80 backdrop-blur border-t flex items-center justify-between z-10">
                <div className="text-sm">
                  <span className="font-bold text-lg">{totalSelected}</span>{' '}
                  produtos selecionados
                </div>
                <Button data-mia-action="final-confirm"
                  size="lg"
                  onClick={handleFinalConfirm}
                  disabled={totalSelected === 0}
                  className="shadow-xl"
                >
                  <Play className="w-4 h-4 mr-2" />
                  Iniciar Análise
                </Button>
              </div>
            </div>
          )}
        </CardContent>
      </Card>

      <SalesMappingModal
        isOpen={isMatchModalOpen}
        onClose={() => setIsMatchModalOpen(false)}
      />
    </div>
  );
}

